import { LitElement, html, css, nothing } from 'lit';
import { EVENT_KEYDOWN, EVENT_OST_OFFER_SELECT, TAG_MODEL_ID_MAPPING } from './constants.js';
import router from './router.js';
import Store from './store.js';
import './rte/osi-field.js';
import './aem/aem-tag-picker-field.js';
import generateFragmentStore from './reactivity/source-fragment-store.js';

export class MasCreateDialog extends LitElement {
    static properties = {
        type: { type: String, reflect: true },
        title: { state: true },
        loading: { state: true },
    };

    static styles = css`
        :host {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: 999;
            display: block;
        }

        .dialog-backdrop {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            z-index: 999;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .loading-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            z-index: 999;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .dialog-container {
            background: var(--spectrum-white);
            border-radius: 20px;
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
            padding: 24px;
            min-width: 400px;
            z-index: 1000;
            position: relative;
        }

        .dialog-header {
            font-size: 18px;
            font-weight: 600;
            margin-bottom: 24px;
            padding-bottom: 16px;
            border-bottom: 1px solid var(--spectrum-gray-200);
        }

        .dialog-footer {
            display: flex;
            justify-content: flex-end;
            gap: 12px;
            margin-top: 24px;
        }

        .form-field {
            margin-bottom: var(calc(var(--swc-scale-factor) * 32px));
        }

        sp-field-label {
            display: block;
            margin-bottom: var(calc(var(--swc-scale-factor) * 8px));
        }

        sp-picker,
        sp-textfield {
            width: 100%;
        }
    `;

    constructor() {
        super();
        this.type = 'merch-card';
        this.title = '';
        this.osi = '';
        this.tags = [];
        this.loading = false;

        this.handleTitleChange = this.handleTitleChange.bind(this);
        this.handleSubmit = this.handleSubmit.bind(this);
        this.close = this.close.bind(this);
        this.handleKeyDown = this.handleKeyDown.bind(this);
        this.handleBackdropClick = this.handleBackdropClick.bind(this);
    }

    connectedCallback() {
        super.connectedCallback();
        document.addEventListener(EVENT_KEYDOWN, this.handleKeyDown);
        document.addEventListener(EVENT_OST_OFFER_SELECT, this.#onOstSelect);
    }

    disconnectedCallback() {
        super.disconnectedCallback();
        document.removeEventListener(EVENT_KEYDOWN, this.handleKeyDown);
        document.removeEventListener(EVENT_OST_OFFER_SELECT, this.#onOstSelect);
    }

    handleKeyDown(event) {
        if (event.key === 'Escape' && !this.loading) {
            this.close();
        }
    }

    handleBackdropClick(event) {
        if (event.target.classList.contains('dialog-backdrop')) {
            this.close();
        }
    }

    /**
     * Normalizes a string to be used as a fragment name
     * Converts to lowercase, replaces spaces with hyphens, and removes special characters
     * @param {string} str - The string to normalize
     * @returns {string} - The normalized string
     */
    normalizeFragmentName(str) {
        if (!str) return '';
        return str
            .toLowerCase()
            .replace(/\s+/g, '-')
            .replace(/[^a-z0-9-]/g, '')
            .replace(/-+/g, '-')
            .replace(/^-|-$/g, '');
    }

    handleTitleChange(value) {
        this.title = value;
    }

    #onOstSelect = ({ detail: { offerSelectorId, offer } }) => {
        if (!offer) return;
        this.osi = offerSelectorId;
    };

    _onTagSelect = ({ detail: { tags } }) => {
        this.tags = tags;
    };

    #handeTagsChange(e) {
        const value = e.target.getAttribute('value');
        this.tags = value ? value.split(',') : [];
    }

    async createFragment(masRepository, fragmentData) {
        const fragment = await masRepository.createFragment(fragmentData);
        const sourceStore = generateFragmentStore(fragment);
        sourceStore.new = true;
        const currentList = Store.fragments.list.data.get() ?? [];
        Store.fragments.list.data.set([sourceStore, ...currentList]);
        this.close();
        await router.navigateToFragmentEditor(fragment.id);
    }

    async tryToCreateFragment(masRepository, fragmentData) {
        try {
            await this.createFragment(masRepository, fragmentData);
            return true;
        } catch (error) {
            console.error(`${error.message} Will try to create again`, error.stack);
            return false;
        }
    }

    getSuffix(offset) {
        let suffix = '';
        const characters = 'abcdefghijklmnopqrstuvwxyz0123456789';
        const charactersLength = characters.length;
        const length = offset + 3;
        for (let i = 0; i < length; i++) {
            suffix += characters.charAt(Math.floor(Math.random() * charactersLength));
        }
        return suffix;
    }

    async handleSubmit(event) {
        if (event) {
            event.preventDefault();
        }

        if (!this.title) {
            return;
        }

        const hasOfferlessTag = this.tags.some((tag) => tag?.includes('offerless'));
        if (this.type === 'merch-card' && !this.osi && !hasOfferlessTag) {
            return;
        }

        this.loading = true;

        const modelId =
            this.type === 'merch-card'
                ? TAG_MODEL_ID_MAPPING['mas:studio/content-type/merch-card']
                : TAG_MODEL_ID_MAPPING['mas:studio/content-type/merch-card-collection'];

        const fragmentData = {
            modelId,
            title: this.title,
            name: this.normalizeFragmentName(this.title),
        };
        if (this.type === 'merch-card') {
            fragmentData.data = {
                osi: this.osi,
                tags: this.tags,
            };
        }

        const masRepository = document.querySelector('mas-repository');
        const firstName = fragmentData.name;
        let nmbOfTries = 0;
        while (!(await this.tryToCreateFragment(masRepository, fragmentData)) && nmbOfTries < 10) {
            nmbOfTries += 1;
            fragmentData.name = `${firstName}-${this.getSuffix(nmbOfTries)}`;
        }
    }

    close() {
        this.title = '';
        this.osi = '';
        this.loading = false;
        this.dispatchEvent(new CustomEvent('close'));
    }

    get dialogTitle() {
        const typeLabel = this.type === 'merch-card' ? 'Merch Card' : 'Merch Card Collection';
        return `Create New ${typeLabel}`;
    }

    render() {
        if (this.loading) {
            return html`
                <div class="loading-overlay">
                    <sp-progress-circle indeterminate size="l"></sp-progress-circle>
                </div>
            `;
        }

        return html`
            <div class="dialog-backdrop" @click=${this.handleBackdropClick}>
                <div class="dialog-container" @click=${(e) => e.stopPropagation()}>
                    <div class="dialog-header">${this.dialogTitle}</div>
                    <div class="dialog-content">
                        <form @submit=${this.handleSubmit}>
                            <div class="form-field">
                                <sp-field-label for="fragment-title" required>Internal title</sp-field-label>
                                <sp-textfield
                                    id="fragment-title"
                                    placeholder="Enter internal fragment title"
                                    value=${this.title}
                                    @input=${(e) => this.handleTitleChange(e.target.value)}
                                    required
                                ></sp-textfield>
                            </div>
                            ${this.type === 'merch-card'
                                ? html`
                                      <div class="form-field">
                                          <sp-field-label for="osi" required>OSI Search</sp-field-label>
                                          <osi-field id="osi" data-field="osi"></osi-field>
                                      </div>
                                      <aem-tag-picker-field
                                          label="Tags"
                                          namespace="/content/cq:tags/mas"
                                          multiple
                                          @change=${this.#handeTagsChange}
                                      ></aem-tag-picker-field>
                                  `
                                : nothing}
                        </form>
                    </div>
                    <div class="dialog-footer">
                        <sp-button variant="secondary" @click=${this.close}>Cancel</sp-button>
                        <sp-button variant="accent" @click=${this.handleSubmit}>Create</sp-button>
                    </div>
                </div>
            </div>
        `;
    }
}

customElements.define('mas-create-dialog', MasCreateDialog);

import { LitElement, html, css } from 'lit';
import { EVENT_KEYDOWN } from './constants.js';
import { showToast } from './utils.js';

const ERROR_TYPES = {
    PERMISSION: { patterns: ['permission', '403'], message: 'You do not have permission to copy this fragment' },
    NOT_FOUND: { patterns: ['not found', '404'], message: 'Fragment not found. It may have been deleted.' },
    NETWORK: { patterns: ['network', 'Network'], message: 'Network error. Please check your connection and try again.' },
};

export class MasCopyDialog extends LitElement {
    static properties = {
        fragment: { type: Object },
        selectedFolder: { state: true },
        selectedLocale: { state: true },
        loading: { state: true },
        error: { state: true },
    };

    static styles = css`
        :host {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            z-index: 999;
            display: block;
        }

        .dialog-backdrop {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(4px);
            z-index: 999;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
        }

        sp-dialog-wrapper {
            z-index: 1000;
            position: relative;
            max-height: 90vh;
            display: flex;
            flex-direction: column;
            background: var(--spectrum-white);
            border-radius: 16px;
            --spectrum-dialog-max-height: 90vh;
            --spectrum-dialog-content-overflow-y: auto;
        }

        .form-field {
            margin-bottom: var(calc(var(--swc-scale-factor) * 32px));
        }

        sp-field-label {
            display: block;
            margin-bottom: var(calc(var(--swc-scale-factor) * 8px));
        }

        .folder-tree {
            max-height: 200px;
            overflow-y: auto;
            border: 1px solid var(--spectrum-gray-300);
            border-radius: 4px;
            padding: 8px;
        }

        .folder-item {
            padding: 4px 8px;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .folder-item:hover {
            background-color: var(--spectrum-gray-200);
        }

        .folder-item.selected {
            background-color: var(--spectrum-blue-400);
            color: white;
        }

        .folder-item.disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        .folder-icon {
            width: 16px;
            height: 16px;
        }

        .current-path {
            font-size: 12px;
            color: var(--spectrum-gray-700);
            margin-bottom: 8px;
        }

        .error-message {
            color: var(--spectrum-red-600);
            font-size: 12px;
            margin-top: 8px;
        }

        sp-textfield {
            width: 100%;
        }

        sp-picker {
            width: 100%;
        }
    `;

    constructor() {
        super();
        this.fragment = null;
        this.selectedFolder = null;
        this.selectedLocale = 'en_US';
        this.loading = false;
        this.error = null;
        this.merchFolders = [];
        this.aem = null;

        this.handleSubmit = this.handleSubmit.bind(this);
        this.close = this.close.bind(this);
        this.handleKeyDown = this.handleKeyDown.bind(this);
    }

    connectedCallback() {
        super.connectedCallback();
        document.addEventListener(EVENT_KEYDOWN, this.handleKeyDown);
        this.aem = document.querySelector('mas-repository')?.aem;

        if (this.aem) {
            this.loadMerchFolders();
        } else {
            this.error = 'AEM instance not available';
            this.loading = false;
        }
    }

    updated(changedProperties) {
        super.updated(changedProperties);

        if (this.aem && this.merchFolders.length === 0 && !this.loading) {
            this.loadMerchFolders();
        }
    }

    disconnectedCallback() {
        super.disconnectedCallback();
        document.removeEventListener(EVENT_KEYDOWN, this.handleKeyDown);
    }

    handleKeyDown(event) {
        if (event.key === 'Escape' && this.dialog?.open) {
            this.close();
        }
    }

    get dialog() {
        return this.shadowRoot.querySelector('sp-dialog-wrapper');
    }

    updated() {
        this.open();
    }

    async open() {
        await this.updateComplete;
        this.dialog.open = true;
    }

    async loadMerchFolders() {
        try {
            this.loading = true;

            const aem = this.aem;
            if (!aem) {
                throw new Error('AEM instance not available');
            }

            const rootPath = '/content/dam/mas';
            const result = await aem.folders.list(rootPath);

            const allowedFolders = ['nala', 'sandbox'];

            this.merchFolders = result.children
                .filter((folder) => allowedFolders.includes(folder.name.toLowerCase()))
                .map((folder) => ({
                    ...folder,
                    displayName: folder.name.replace(/-/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase()),
                    fullPath: folder.path,
                }));

            this.loading = false;
        } catch (err) {
            this.error = 'Failed to load folders';
            this.loading = false;
            console.error('Error loading folders:', err);
        }
    }

    selectFolder(folder) {
        this.selectedFolder = folder;
        this.error = null;
    }

    validateInputs() {
        if (!this.selectedFolder) {
            this.error = 'Please select a destination folder';
            return false;
        }

        if (!this.aem) {
            this.error = 'AEM instance not available';
            return false;
        }

        if (!this.fragment?.path) {
            this.error = 'Fragment is missing path property';
            return false;
        }

        return true;
    }

    showSuccessMessage(copiedFragment) {
        const folderName = this.selectedFolder.displayName;
        const localeName = this.selectedLocale;
        showToast(`Fragment copied to ${folderName} (${localeName})`, 'positive');
    }

    handleCopyError(error) {
        this.error = error.message || 'Failed to copy fragment';
        this.loading = false;

        const errorMessage = error.message || '';

        for (const [, config] of Object.entries(ERROR_TYPES)) {
            if (config.patterns.some((pattern) => errorMessage.includes(pattern))) {
                showToast(config.message, 'negative');
                return;
            }
        }

        showToast(`Failed to copy fragment: ${error.message}`, 'negative');
    }

    extractSubfolderPath() {
        if (!this.fragment?.path || !this.selectedFolder?.fullPath) {
            return '';
        }

        const fragmentPath = this.fragment.path;
        const surfacePath = this.selectedFolder.fullPath;

        const pathParts = fragmentPath.split('/');
        const surfaceParts = surfacePath.split('/');

        const surfaceIndex = pathParts.findIndex(
            (part, idx) => idx < pathParts.length - 2 && part === surfaceParts[surfaceParts.length - 1],
        );

        if (surfaceIndex === -1) return '';

        const localeIndex = pathParts.findIndex((part, idx) => idx > surfaceIndex && /^[a-z]{2}_[A-Z]{2}$/.test(part));

        if (localeIndex === -1 || localeIndex <= surfaceIndex + 1) return '';

        return pathParts.slice(surfaceIndex + 1, localeIndex).join('/');
    }

    async performCopy() {
        const subfolderPath = this.extractSubfolderPath();
        const targetPath = subfolderPath ? `${this.selectedFolder.fullPath}/${subfolderPath}` : this.selectedFolder.fullPath;

        const copiedFragment = await this.aem.sites.cf.fragments.copyToFolder(
            this.fragment,
            targetPath,
            null,
            this.selectedLocale,
        );

        if (!copiedFragment) {
            throw new Error('Copy operation completed but could not retrieve copied fragment');
        }

        return copiedFragment;
    }

    async handleSubmit() {
        if (!this.validateInputs()) return;

        try {
            this.loading = true;
            showToast(`Copying fragment to ${this.selectedFolder.displayName}...`);

            const copiedFragment = await this.performCopy();
            this.showSuccessMessage(copiedFragment);

            this.dispatchEvent(
                new CustomEvent('fragment-copied', {
                    detail: { fragment: copiedFragment },
                    bubbles: true,
                    composed: true,
                }),
            );
        } catch (err) {
            this.handleCopyError(err);
        }
    }

    close() {
        this.dialog.open = false;
        this.dispatchEvent(
            new CustomEvent('cancel', {
                bubbles: true,
                composed: true,
            }),
        );
    }

    render() {
        return html`
            <div class="dialog-backdrop" @click=${this.handleBackdropClick}>
                <sp-dialog-wrapper
                    headline="Copy fragment"
                    mode="modal"
                    confirm-label="Copy"
                    cancel-label="Cancel"
                    @confirm=${this.handleSubmit}
                    @cancel=${this.close}
                    ?dismissable=${!this.loading}
                    @click=${(e) => e.stopPropagation()}
                >
                    <div class="form-field">
                        <sp-field-label for="locale-picker">Select Locale</sp-field-label>
                        <mas-locale-picker
                            id="locale-picker"
                            locale=${this.selectedLocale}
                            @locale-changed=${(e) => (this.selectedLocale = e.detail.locale)}
                        ></mas-locale-picker>
                    </div>

                    <div class="form-field">
                        <sp-field-label for="folder-picker">Select Destination Folder</sp-field-label>

                        ${this.loading
                            ? html` <sp-progress-circle indeterminate></sp-progress-circle> `
                            : html`
                                  <div class="folder-tree">
                                      ${this.merchFolders.length === 0
                                          ? html`<div class="error-message">No folders available</div>`
                                          : this.merchFolders.map((folder) => {
                                                return html`
                                                    <div
                                                        class="folder-item ${this.selectedFolder?.fullPath === folder.fullPath
                                                            ? 'selected'
                                                            : ''}"
                                                        @click=${() => this.selectFolder(folder)}
                                                        title="${folder.fullPath}"
                                                    >
                                                        <sp-icon-folder size="m" class="folder-icon"></sp-icon-folder>
                                                        <span>${folder.displayName}</span>
                                                    </div>
                                                `;
                                            })}
                                  </div>
                              `}
                        ${this.error ? html` <div class="error-message">${this.error}</div> ` : ''}
                    </div>
                </sp-dialog-wrapper>
            </div>
        `;
    }

    handleBackdropClick(event) {
        if (event.target.classList.contains('dialog-backdrop') && !this.loading) {
            this.close();
        }
    }
}

customElements.define('mas-copy-dialog', MasCopyDialog);

import { LitElement, html, nothing } from 'lit';
import { styles } from './mas-quick-actions.css.js';
import { QUICK_ACTION } from './constants.js';

const ACTION_CONFIG = {
    [QUICK_ACTION.SAVE]: {
        icon: 'sp-icon-save-floppy',
        title: 'Save',
    },
    [QUICK_ACTION.DUPLICATE]: {
        icon: 'sp-icon-duplicate',
        title: 'Duplicate',
    },
    [QUICK_ACTION.PUBLISH]: {
        icon: 'sp-icon-publish',
        title: 'Publish',
    },
    [QUICK_ACTION.UNPUBLISH]: {
        icon: 'sp-icon-publish-remove',
        title: 'Unpublish',
    },
    [QUICK_ACTION.CANCEL]: {
        icon: 'sp-icon-undo',
        title: 'Cancel',
    },
    [QUICK_ACTION.COPY]: {
        icon: 'sp-icon-code',
        title: 'Copy code',
    },
    [QUICK_ACTION.LOCK]: {
        icon: 'sp-icon-lock-closed',
        title: 'Lock',
    },
    [QUICK_ACTION.DISCARD]: {
        icon: 'sp-icon-undo',
        title: 'Discard',
    },
    [QUICK_ACTION.DELETE]: {
        icon: 'sp-icon-delete',
        title: 'Delete',
        className: 'delete-action',
    },
    [QUICK_ACTION.LOC]: {
        icon: 'custom-icon-send-to-loc',
        title: 'Send to Localization',
    },
};

class MasQuickActions extends LitElement {
    static styles = styles;

    static properties = {
        isDraggable: { type: Boolean },
        actions: { type: Array },
        disabled: { type: Set },
        _dragging: { type: Boolean, state: true },
    };

    #posX = null;
    #posY = null;
    #startX = 0;
    #startY = 0;
    #initialX = 0;
    #initialY = 0;

    constructor() {
        super();
        this.isDraggable = true;
        this.actions = [];
        this.disabled = new Set();
        this._dragging = false;
    }

    #getEventCoordinates(e) {
        if (e.touches && e.touches.length > 0) {
            return { clientX: e.touches[0].clientX, clientY: e.touches[0].clientY };
        }
        return { clientX: e.clientX, clientY: e.clientY };
    }

    #handleDragStart(e) {
        if (!this.isDraggable) return;
        e.preventDefault();
        this._dragging = true;
        const { clientX, clientY } = this.#getEventCoordinates(e);
        this.#startX = clientX;
        this.#startY = clientY;
        const toolbar = this.shadowRoot?.querySelector('.quick-actions-toolbar');
        if (toolbar) {
            const rect = toolbar.getBoundingClientRect();
            this.#initialX = rect.left + rect.width / 2;
            this.#initialY = window.innerHeight - rect.bottom;
        }
        document.addEventListener('mousemove', this.#handleDrag);
        document.addEventListener('mouseup', this.#handleDragEnd);
        document.addEventListener('touchmove', this.#handleDrag, { passive: false });
        document.addEventListener('touchend', this.#handleDragEnd);
    }

    #handleDrag = (e) => {
        if (!this._dragging) return;
        e.preventDefault();
        const { clientX, clientY } = this.#getEventCoordinates(e);
        const deltaX = clientX - this.#startX;
        const deltaY = clientY - this.#startY;
        let newX = this.#initialX + deltaX;
        let newY = this.#initialY - deltaY;
        const toolbar = this.shadowRoot?.querySelector('.quick-actions-toolbar');
        if (toolbar) {
            const rect = toolbar.getBoundingClientRect();
            const halfWidth = rect.width / 2;
            const height = rect.height;
            newX = Math.max(halfWidth, Math.min(newX, window.innerWidth - halfWidth));
            newY = Math.max(0, Math.min(newY, window.innerHeight - height - 24));
        }
        this.#posX = newX;
        this.#posY = newY;
        this.requestUpdate();
    };

    #handleDragEnd = () => {
        this._dragging = false;
        document.removeEventListener('mousemove', this.#handleDrag);
        document.removeEventListener('mouseup', this.#handleDragEnd);
        document.removeEventListener('touchmove', this.#handleDrag);
        document.removeEventListener('touchend', this.#handleDragEnd);
    };

    disconnectedCallback() {
        super.disconnectedCallback();
        this.#handleDragEnd();
    }

    resetPosition() {
        this.#posX = null;
        this.#posY = null;
        this.requestUpdate();
    }

    get dragHandle() {
        if (!this.isDraggable) return nothing;
        return html`
            <div
                class="drag-handle"
                title="Drag to reposition"
                @mousedown=${(e) => this.#handleDragStart(e)}
                @touchstart=${(e) => this.#handleDragStart(e)}
            >
                <svg
                    id="Layer_1"
                    data-name="Layer 1"
                    xmlns="http://www.w3.org/2000/svg"
                    width="26"
                    height="26"
                    viewBox="0 0 18 18"
                >
                    <defs>
                        <style>
                            .fill {
                                fill: #464646;
                            }
                        </style>
                    </defs>

                    <rect id="Canvas" fill="#ff13dc" opacity="0" width="18" height="18" />

                    <circle class="fill" cx="7" cy="13" r="1" />
                    <circle class="fill" cx="7" cy="10" r="1" />
                    <circle class="fill" cx="7" cy="7" r="1" />
                    <circle class="fill" cx="7" cy="4" r="1" />

                    <circle class="fill" cx="10" cy="13" r="1" />
                    <circle class="fill" cx="10" cy="10" r="1" />
                    <circle class="fill" cx="10" cy="7" r="1" />
                    <circle class="fill" cx="10" cy="4" r="1" />
                </svg>
            </div>
